const a="http://localhost:3000/api/devops";class c{baseUrl;constructor(){this.baseUrl=a}async getSystemMetrics(){try{const e=await $fetch(`${this.baseUrl}/system/metrics`,{method:"GET"});return e.success?e.data:null}catch(e){return console.error("Failed to fetch system metrics:",e),null}}async getDevTools(e){try{const t=e?`?category=${e}`:"",s=await $fetch(`${this.baseUrl}/tools${t}`,{method:"GET"});return s.success?s.data:[]}catch(t){return console.error("Failed to fetch development tools:",t),[]}}async getDevTool(e){try{const t=await $fetch(`${this.baseUrl}/tools/${e}`,{method:"GET"});return t.success?t.data:null}catch(t){return console.error(`Failed to fetch development tool ${e}:`,t),null}}async launchDevTool(e,t){try{const s=await $fetch(`${this.baseUrl}/tools/${e}/launch`,{method:"POST",headers:{"Content-Type":"application/json"},body:{config:t}});return s.success?{success:!0,sessionId:s.data.sessionId,url:s.data.url,port:s.data.port,message:s.message}:{success:!1,message:s.message}}catch(s){return console.error(`Failed to launch development tool ${e}:`,s),{success:!1,message:"Failed to launch tool"}}}async stopDevTool(e,t){try{return(await $fetch(`${this.baseUrl}/tools/${e}/stop`,{method:"POST",headers:{"Content-Type":"application/json"},body:{sessionId:t}})).success}catch(s){return console.error(`Failed to stop development tool ${e}:`,s),!1}}async getDevToolStats(){try{const e=await $fetch(`${this.baseUrl}/tools/stats`,{method:"GET"});return e.success?e.data:{totalTools:0,activeTools:0,totalSessions:0,averageSessionTime:0,popularTools:[],activeSessions:0}}catch(e){return console.error("Failed to fetch development tool statistics:",e),{totalTools:0,activeTools:0,totalSessions:0,averageSessionTime:0,popularTools:[],activeSessions:0}}}async getDevEnvironments(e,t){try{const s=new URLSearchParams;e&&s.append("type",e),t&&s.append("status",t);const o=s.toString(),n=`${this.baseUrl}/environments${o?`?${o}`:""}`,r=await $fetch(n,{method:"GET"});return r.success?r.data:[]}catch(s){return console.error("Failed to fetch development environments:",s),[]}}async createDevEnvironment(e){try{const t=await $fetch(`${this.baseUrl}/environments`,{method:"POST",headers:{"Content-Type":"application/json"},body:e});return t.success?t.data:null}catch(t){return console.error("Failed to create development environment:",t),null}}async startDevEnvironment(e){try{return(await $fetch(`${this.baseUrl}/environments/${e}/start`,{method:"POST"})).success}catch(t){return console.error(`Failed to start development environment ${e}:`,t),!1}}async stopDevEnvironment(e){try{return(await $fetch(`${this.baseUrl}/environments/${e}/stop`,{method:"POST"})).success}catch(t){return console.error(`Failed to stop development environment ${e}:`,t),!1}}async executeCode(e){try{const t=await $fetch(`${this.baseUrl}/execute`,{method:"POST",headers:{"Content-Type":"application/json"},body:e});return t.success?t.data:{success:!1,error:"Execution failed",executionTime:0,memoryUsed:0,exitCode:-1}}catch(t){return console.error("Failed to execute code:",t),{success:!1,error:"Execution failed",executionTime:0,memoryUsed:0,exitCode:-1}}}async getSupportedLanguages(){try{const e=await $fetch(`${this.baseUrl}/execute/languages`,{method:"GET"});return e.success?e.data.map(t=>t.name):[]}catch(e){return console.error("Failed to fetch supported languages:",e),[]}}async getPythonStatus(){try{const e=await $fetch("http://localhost:3000/python/status");return e.success?e.data:null}catch(e){return console.error("Failed to fetch python status:",e),null}}async setupPython(){try{return await $fetch("http://localhost:3000/python/setup",{method:"POST"})}catch(e){return console.error("Failed to setup python:",e),null}}}const i=new c;export{i as d};
